import React, { useState, useEffect } from "react";
import axios from "../Https/Axios";
import 'bootstrap/dist/css/bootstrap.min.css';
import jsPDF from "jspdf";
import { jwtDecode } from "jwt-decode";

export default function AttendanceDetail() {
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [attendanceData, setAttendanceData] = useState([]);

  useEffect(() => {


    const token = localStorage.getItem("emsemployeelogintoken");
    const decoded = token ? jwtDecode(token) : {};
    const employeeId = decoded.id;
    axios
      .get(`/api/attendances/employee/${employeeId}`)
      .then((response) => {
        console.log(response)
        const formattedData = response.data.map((entry) => {
          const dateObj = new Date(entry.date);
          const date = dateObj.toISOString().split("T")[0];
          const timeIn = entry.checkIn ? new Date(entry.checkIn).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : "-";
          const timeOut = entry.checkOut ? new Date(entry.checkOut).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : "-";
          const status = entry.status === "present" ? "Present" : "Absent";

          const breaks = entry.breaks.map(b => ({
            start: new Date(b.breakStart).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            end: new Date(b.breakEnd).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          }));

          return {
            date,
            timeIn,
            timeOut,
            status,
            breaks
          };
        });

        setAttendanceData(formattedData);
      })
      .catch((error) => {
        console.error("Error fetching attendance data:", error);
      });
  }, []);

  const filteredData = attendanceData.filter(record => {
    if (!fromDate && !toDate) return true;
    const recordDate = new Date(record.date);
    if (fromDate && recordDate < new Date(fromDate)) return false;
    if (toDate && recordDate > new Date(toDate)) return false;
    return true;
  });

  const exportPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(16);
    doc.text("Attendance Records", 14, 20);
    doc.setFontSize(12);

    const startX = 14;
    let currentY = 30;
    doc.text("Date", startX, currentY);
    doc.text("Sign In", startX + 40, currentY);
    doc.text("Sign Out", startX + 80, currentY);
    doc.text("Status", startX + 120, currentY);

    currentY += 10;
    filteredData.forEach(record => {
      doc.text(record.date, startX, currentY);
      doc.text(record.timeIn, startX + 40, currentY);
      doc.text(record.timeOut, startX + 80, currentY);
      doc.text(record.status, startX + 120, currentY);
      currentY += 10;
    });

    doc.save("attendance_records.pdf");
  };

  return (
    <div className="container my-4">
      <h1
        className="text-dark text-center mb-3"
        >
        Attendance Details
      </h1>

      <div className="row my-3 align-items-end">
        <div className="col-sm-5 col-md-3">
          <label htmlFor="fromDate" className="form-label">From Date</label>
          <input
            type="date"
            id="fromDate"
            className="form-control"
            value={fromDate}
            onChange={e => setFromDate(e.target.value)}
          />
        </div>
        <div className="col-sm-5 col-md-3">
          <label htmlFor="toDate" className="form-label">To Date</label>
          <input
            type="date"
            id="toDate"
            className="form-control"
            value={toDate}
            onChange={e => setToDate(e.target.value)}
          />
        </div>
        <div className="col-sm-12 col-md-3 d-flex gap-2 mt-3 mt-md-0"></div>
        <div className="col-sm-12 col-md-3 d-flex gap-2 mt-3 mt-md-0">
          <button
            className="btn flex-grow-1 text-white fw-bold"
            onClick={exportPDF}
            style={{ backgroundColor: "#E100FF" }}
          >
            Export PDF
          </button>
        </div>
      </div>

      <div className="table-responsive shadow-sm rounded">
        <table className="table custom-table">
            <tr  style={{ background: "linear-gradient(135deg, #ff0055, #E100FF)", color: "white" }}>
              <th>Date</th>
              <th>Sign In</th>
              <th>Sign Out</th>
              <th>Status</th>
              <th>Breaks</th>
            </tr>
          <tbody>
            {filteredData.length === 0 ? (
              <tr>
                <td colSpan="5" className="text-center">No records found for selected date range.</td>
              </tr>
            ) : (
              filteredData.map((record, idx) => (
                <tr key={idx}>
                  <td>{record.date}</td>
                  <td>{record.timeIn}</td>
                  <td>{record.timeOut}</td>
                  <td>
                    <span
                      style={{
                        color:
                          record.status === "Present"
                            ? "#ff0055"
                            : record.status === "Absent"
                              ? "#E100FF"
                              : "orange"
                      }}
                    >
                      {record.status}
                    </span>
                  </td>
                  <td>
                    {record.breaks.length > 0 ? (
                      <span
                        className="badge bg-green-500 p-2 text-white"
                        title={record.breaks
                          .map((b, i) => `Break ${i + 1}: ${b.start} - ${b.end}`)
                          .join('\n')}
                      >
                        {record.breaks.length} break{record.breaks.length > 1 ? "s" : ""}
                      </span>
                    ) : (
                      <span>No breaks</span>
                    )}
                  </td>


                </tr>
              ))
            )}
          </tbody>

        </table>
      </div>
    </div>
  );
}