import React, { useState, useEffect } from 'react';
import DashBoardNavbar from './Sidebar';

export default function Dashboard({ children }) {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isMdUp, setIsMdUp] = useState(window.innerWidth >= 768);

  const toggleSidebar = () => setSidebarOpen(!sidebarOpen);

  useEffect(() => {
    function handleResize() {
      setIsMdUp(window.innerWidth >= 768);
    }
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <div className="d-md-flex ">
      <DashBoardNavbar isOpen={sidebarOpen} toggleSidebar={toggleSidebar} />

      <div
        className="flex-grow-1 p-3 mt-5 mt-md-0"
        style={{
          marginLeft: sidebarOpen && isMdUp ? '240px' : '0',
          transition: 'margin-left 0.3s ease',
        }}
      >
        {children}
      </div>
    </div>
  );
}