import React, { useEffect, useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import Axios from "../Https/Axios"; // Axios instance
import { Notification as NotificationAPI } from "../Https/AdminSideAxiosUrls"; 

export default function Notification() {
  const [notifications, setNotifications] = useState([]);
  const [searchKeyword, setSearchKeyword] = useState("");
  const [searchDate, setSearchDate] = useState("");

  useEffect(() => {
    Axios.get(NotificationAPI)
      .then((res) => {
        const updatedData = res.data.map((item) => ({
          ...item,
          isRead: false, 
        }));
        setNotifications(updatedData);
      })
      .catch((err) => {
        console.error("Error fetching notifications:", err);
      });
  }, []);

  // Search filter logic
  const filteredNotifications = notifications.filter((n) => {
    const createdDate = new Date(n.createdAt).toISOString().split("T")[0]; // 'YYYY-MM-DD'
    return (
      n.title.toLowerCase().includes(searchKeyword.toLowerCase()) &&
      (searchDate === "" || createdDate === searchDate)
    );
  });

  return (
    <div className="container py-4">
      <h2 className=" mb-4 text-dark">🔔 Notifications</h2>

      {/* Search & Date Filters */}
      <div className="row justify-content-start align-items-end mb-4">
        <div className="col-md-5 mb-2">
          <input
            type="text"
            className="form-control"
            placeholder="🔍 Search by title..."
            value={searchKeyword}
            onChange={(e) => setSearchKeyword(e.target.value)}
          />
        </div>
        <div className="col-md-4 mb-2">
          <input
            type="date"
            className="form-control"
            value={searchDate}
            onChange={(e) => setSearchDate(e.target.value)}
          />
        </div>
        <div className="col-md-3 mb-2">
          <button
            className="btn text-white fw-bold w-100"
            style={{ backgroundColor: "#E100FF", whiteSpace: "nowrap" }}
            onClick={() => {
              setSearchKeyword("");
              setSearchDate("");
            }}
          >
             Reset Filters
          </button>
        </div>
      </div>


      {/* Notification Cards */}
      <div className="row justify-content-start">
{filteredNotifications.map((notification, index) => {
  const bgColor =
    index % 2 === 0
      ? "linear-gradient(135deg, #ff0055, #E100FF)"
      : "linear-gradient(135deg, #E100FF, #ff0055)";

  return (
    <div className="col-12 col-lg-12 mb-3" key={notification._id}>
      <div
        className="p-3 rounded shadow"
        style={{
          backgroundImage: notification.isRead ? "none" : bgColor,
          backgroundColor: notification.isRead ? "#ffffff" : "transparent",
          color: notification.isRead ? "#333" : "#fff",
          border: notification.isRead ? "1px solid #eee" : "none",
          transition: "0.3s",
        }}
      >
        <div className="d-flex justify-content-between small">
          <h6 className="mb-2 fw-bold">{notification.title}</h6>
          <span>📅 {new Date(notification.createdAt).toLocaleDateString()}</span>
        </div>
        <p>{notification.message}</p>
      </div>
    </div>
  );
})}


      </div>
    </div>
  );
}
