import React, { useEffect, useState } from "react";
import {
  FaCheckCircle,
  FaHourglassHalf,
  FaUserTie,
  FaInfoCircle,
} from "react-icons/fa";
import Axios from "../Https/Axios";
import { ProgressBar, Badge, Nav } from "react-bootstrap";
import { jwtDecode } from "jwt-decode";

export default function Project() {
  const [projects, setProjects] = useState([]);
  const [activeFilter, setActiveFilter] = useState("All");

  const token = localStorage.getItem("emsemployeelogintoken");
      const decoded = token ? jwtDecode(token) : {};
      const employeeId = decoded.id;

  const fetchProjects = async () => {
    try {
      const res = await Axios.get(`/api/projects/by-employee/${employeeId}`);
      setProjects(res.data);
    } catch (error) {
      console.error("Error fetching projects:", error);
    }
  };

  useEffect(() => {
    fetchProjects();
  }, []);

  const statusCounts = {
    "Not Started": projects.filter((p) => p.status === "Not Started").length,
    "In Progress": projects.filter((p) => p.status === "In Progress").length,
    Completed: projects.filter((p) => p.status === "Completed").length,
  };

  const filteredProjects =
    activeFilter === "All"
      ? projects
      : projects.filter((p) => p.status === activeFilter);

  const getProgress = (status) => {
    if (status === "Completed") return 100;
    if (status === "In Progress") return 50;
    return 0;
  };

  const getBadgeStyle = (status) => {
    if (status === "Completed")
      return { backgroundColor: "#E100FF", color: "white" };
    if (status === "In Progress")
      return { backgroundColor: "#FF0055", color: "white" };
    return { backgroundColor: "gray", color: "white" };
  };

  const getProgressStyle = (status) => {
    if (status === "Completed") {
      return {
        backgroundColor: "#e0e0e0", // track color
      };
    } else if (status === "In Progress") {
      return {
        backgroundColor: "#e0e0e0", // track color
      };
    } else {
      return {
        backgroundColor: "#e0e0e0",
      };
    }
  };


  return (
    <div className="container ">
      <h2 className="fw-bold mb-4 text-dark">Assigned Projects</h2>

     <Nav
  variant="tabs"
  className="p-2 rounded mb-4"
  activeKey={activeFilter}
  onSelect={setActiveFilter}
>
  <Nav.Item>
    <Nav.Link
      eventKey="All"
      className={`fw-bold ${activeFilter === "All" ? "bg-dark text-white" : "text-white"}`}
    >
      All <Badge bg="dark">{projects.length}</Badge>
    </Nav.Link>
  </Nav.Item>
  <Nav.Item>
    <Nav.Link
      eventKey="Not Started"
      className={`fw-bold ${activeFilter === "Not Started" ? "bg-dark text-white" : "text-white"}`}
    >
      Not Started{" "}
      <Badge style={{ backgroundColor: "gray", color: "white" }}>
        {statusCounts["Not Started"]}
      </Badge>
    </Nav.Link>
  </Nav.Item>
  <Nav.Item>
    <Nav.Link
      eventKey="In Progress"
      className={`fw-bold ${activeFilter === "In Progress" ? "bg-dark text-white" : "text-white"}`}
    >
      In Progress{" "}
      <Badge className="custom-badge-in-progress">
        {statusCounts["In Progress"]}
      </Badge>
    </Nav.Link>
  </Nav.Item>
  <Nav.Item>
    <Nav.Link
      eventKey="Completed"
      className={`fw-bold ${activeFilter === "Completed" ? "bg-dark text-white" : "text-white"}`}
    >
      Completed{" "}
      <Badge className="custom-badge-completed">
        {statusCounts["Completed"]}
      </Badge>
    </Nav.Link>
  </Nav.Item>
</Nav>


      {/* Projects Grid */}
      <div className="row">
        {filteredProjects.length === 0 ? (
          <div className="text-center text-muted mt-4">No projects found.</div>
        ) : (
          filteredProjects.map((project) => {
            const assignedBy =
              project.employees.find((emp) => emp._id === employeeId)?.name ||
              "Unknown";

            return (
              <div className="col-md-6 col-lg-4 mb-4" key={project._id}>
                <div className="card shadow-sm h-100">
                  <div className="card-body">
                    <h5 className="card-title d-flex align-items-center gap-2">
                      <FaInfoCircle color="#6610f2" /> {project.name}
                    </h5>
                    <p className="card-text">{project.description}</p>

                    <div className="mb-2 text-muted">
                      <strong>Start:</strong>{" "}
                      {new Date(project.startDate).toLocaleDateString()}
                      <br />
                      <strong>End:</strong>{" "}
                      {new Date(project.endDate).toLocaleDateString()}
                    </div>

                    <Badge
                      className={`mb-2 ${project.status === "Completed"
                        ? "custom-badge-completed"
                        : project.status === "In Progress"
                          ? "custom-badge-in-progress"
                          : "custom-badge-not-started"
                        }`}
                    >
                      {project.status}
                    </Badge>


                    <ProgressBar
                      now={getProgress(project.status)}
                      label={`${getProgress(project.status)}%`}
                      className={`mb-3 ${project.status === "Completed"
                          ? "custom-progress-completed"
                          : project.status === "In Progress"
                            ? "custom-progress-inprogress"
                            : "custom-progress-notstarted"
                        }`}
                    />


                    <div className="text-muted fst-italic">
                      <FaUserTie /> Assigned by: {assignedBy}
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}