import React, { useEffect, useState } from "react";
import Axios from "../Https/Axios";
import { jwtDecode } from "jwt-decode";
import {
  Notification as NotificationAPI,
  Leaves,
} from "../Https/AdminSideAxiosUrls";

import {
FaTasks,
  FaUserPlus,
  FaEnvelopeOpenText,
  FaUserCircle,
  FaCalendarTimes
} from "react-icons/fa";

import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  Legend,
} from "recharts";

const DashboardHome = () => {
  const [notificationCount, setNotificationCount] = useState(0);
  const [pendingLeaves, setPendingLeaves] = useState(0);
  const [projectCount, setProjectCount] = useState(0);
  const [recentNotifications, setRecentNotifications] = useState([]);
  const [presentCount, setPresentCount] = useState(0);
  const [absentCount, setAbsentCount] = useState(0);
  const [employeeName, setEmployeeName] = useState("");

  const token = localStorage.getItem("emsemployeelogintoken");
  let employeeId = null;

  try {
    const decoded = token ? jwtDecode(token) : {};
    employeeId = decoded.id;
  } catch (err) {
    console.error("Invalid token:", err);
  }

  const today = new Date().toISOString().split("T")[0];

  useEffect(() => {
    const fetchEmployee = async () => {
      if (!token) return;
      try {
        const decoded = jwtDecode(token);
        const id = decoded.id || decoded._id;
        const res = await Axios.get(`/api/employees/${id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        setEmployeeName(res.data.name);
      } catch (err) {
        console.error("Failed to fetch employee:", err);
      }
    };
    fetchEmployee();
  }, [token]);

  useEffect(() => {
    if (!employeeId) return;

    const fetchData = async () => {
      try {
        const notificationRes = await Axios.get(
          `${NotificationAPI}?employeeId=${employeeId}&_=${Date.now()}`
        );
        const notifications = Array.isArray(notificationRes.data)
          ? notificationRes.data
          : [];
        setNotificationCount(notifications.length);

        const latestNotifications = notifications
          .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
          .slice(0, 3)
          .map((notif) => ({
            title: notif.title || "No title",
            message: notif.message || "No message content",
            date: notif.createdAt
              ? new Date(notif.createdAt).toISOString().split("T")[0]
              : "",
            time: notif.createdAt
              ? new Date(notif.createdAt).toLocaleTimeString([], {
                  hour: "2-digit",
                  minute: "2-digit",
                })
              : "",
          }));

        setRecentNotifications(latestNotifications);

        const leaveRes = await Axios.get(`${Leaves}/employee/${employeeId}`);
        if (Array.isArray(leaveRes.data)) {
          const pending = leaveRes.data.filter(
            (item) => item.status?.toLowerCase() === "pending"
          );
          setPendingLeaves(pending.length);
        }

        const projectRes = await Axios.get(
          `/api/projects/by-employee/${employeeId}`
        );
        if (Array.isArray(projectRes.data)) {
          setProjectCount(projectRes.data.length);
        }

        const attendanceListRes = await Axios.get(
          `/api/attendances/employee/${employeeId}`
        );
        if (Array.isArray(attendanceListRes.data)) {
          const present = attendanceListRes.data.filter(
            (item) => item.status?.toLowerCase() === "present"
          ).length;
          const absent = attendanceListRes.data.filter(
            (item) => item.status?.toLowerCase() === "absent"
          ).length;
          setPresentCount(present);
          setAbsentCount(absent);
        }
      } catch (error) {
        console.error("Error fetching dashboard data:", error);
      }
    };

    fetchData();
  }, [employeeId, today]);

  const stats = [
 {
  icon: <FaUserCircle size={28} />,
  count: `Welcome, ${(employeeName?.split(" ")[0]) || "Employee"}`,
},

    {
    icon: <FaTasks size={28} />,
      count: projectCount,
      label: "Active projects",
    },
    {
    icon: <FaCalendarTimes size={28} />,
      count: pendingLeaves,
      label: "Pending leaves ",
    },
    {
    icon: <FaEnvelopeOpenText size={28} />,
      count: notificationCount,
      label: "Recent notifications",
    },
  ];

  const attendancePieData = [
    { name: "Present", value: presentCount },
    { name: "Absent", value: absentCount },
  ];

  return (
    <div className="container py-4">
      <h2 className="fw-bold mb-1 text-center"> Dashboard </h2>
      <p className="text-muted mb-4 text-center">Welcome! to the ODL Dashboard.</p>

      {/* Stats Section */}
      <div className="row g-4 mb-5">
        {stats.map((stat, index) => (
          <div className="col-12 col-lg-3 col-sm-6 col-md-6" key={index}>
            <div className="card shadow-sm border-0 h-100">
              <div className="card-body d-flex align-items-center gap-3">
                <div className="bg-light text p-3 rounded-circle">{stat.icon}</div>
                <div>
                  <small className="text-secondary">{stat.label}</small>
                  <h5 className="mb-0 fw-bold text text-muted">
                    {stat.count}
                  </h5>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Charts Section */}
      <div className="row g-4 mb-5">
        {/* Bar Chart */}
        <div className="col-md-6">
          <div className="card shadow-sm border-0">
            <div className="card-body">
              <h5 className="fw-semibold mb-3">Dashboard Stats Overview</h5>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart
                  data={[
                    { name: "Notifications", value: notificationCount },
                    { name: "Pending Leaves", value: pendingLeaves },
                    { name: "Projects", value: projectCount },
                  ]}
                  margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
                >
                  <defs>
                    <linearGradient id="statsGradient" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#ff0055" />
                      <stop offset="100%" stopColor="#E100FF" />
                    </linearGradient>
                  </defs>

                  <XAxis dataKey="name" />
                  <YAxis allowDecimals={false} />
                  <Tooltip />
                  <Bar dataKey="value" fill="url(#statsGradient)" radius={[8, 8, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>

        {/* Pie Chart */}
        <div className="col-md-6">
          <div className="card shadow-sm border-0">
            <div className="card-body">
              <h5 className="fw-semibold mb-3">Attendance: Present vs Absent</h5>
              <ResponsiveContainer width="100%" height={300}>
                <PieChart>
                  <Pie
                    data={attendancePieData}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    outerRadius={90}
                    label={({ name, value, percent }) =>
                      `${name}: ${value} (${(percent * 100).toFixed(0)}%)`
                    }
                  >
                    {attendancePieData.map((entry, index) => (
                      <Cell
                        key={`cell-${index}`}
                        fill={index === 0 ? "#ff0055" : "#7a00ff"}
                      />
                    ))}
                  </Pie>
                  <Legend />
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      </div>

      {/* Notifications */}
      <div className="mb-5">
        <h4 className="mb-3">Recent Notifications</h4>
        <div className="list-group shadow-sm">
          {recentNotifications.length > 0 ? (
            recentNotifications.map((notif, i) => (
              <div key={i} className="list-group-item list-group-item-action">
                <div className="d-flex justify-content-between align-items-start">
                  <div>
                    <h6 className="fw-semibold mb-1">{notif.title}</h6>
                    <p className="mb-1 small text-muted">{notif.message}</p>
                  </div>
                  <small className="text-muted">
                    {notif.date} | {notif.time}
                  </small>
                </div>
              </div>
            ))
          ) : (
            <p className="text-muted px-3">No recent notifications</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default DashboardHome;
