import React, { useState, useEffect } from "react";
import { jwtDecode } from "jwt-decode";
import axios from "../Https/Axios";
import { FaUserCircle } from "react-icons/fa";

export default function Project() {
  const token = localStorage.getItem("emsemployeelogintoken");

  let employeeId = null;
  if (token) {
    try {
      const decoded = jwtDecode(token);
      employeeId = decoded?.id;
    } catch (err) {
      console.error("Invalid token:", err.message);
    }
  }

  const [employee, setEmployee] = useState(null);
  const [editContact, setEditContact] = useState("");
  const [editImage, setEditImage] = useState("");
  const [oldPass, setOldPass] = useState("");
  const [newPass, setNewPass] = useState("");

  useEffect(() => {
    async function fetchEmployee() {
      if (!token || !employeeId) return;
      try {
        const res = await axios.get(`api/employees/${employeeId}`);
        const data = res.data;
        setEmployee(data);
        setEditContact(data.contact || "");
        setEditImage(data.image || "");
      } catch (err) {
        console.error(err);
        alert(err.message);
      }
    }

    fetchEmployee();
  }, [employeeId, token]);

  const handleProfileUpdate = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`http://localhost:3004/api/employees/${employeeId}`, {
        method: "PUT",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ contact: editContact, image: editImage }),
      });
      if (!res.ok) throw new Error("Update failed");
      const updated = await res.json();
      setEmployee(updated);
      alert("Profile updated successfully!");
    } catch (err) {
      alert(err.message);
    }
  };

  const handleChangePassword = async (e) => {
    e.preventDefault();
    if (!oldPass || !newPass) {
      alert("Please fill both password fields");
      return;
    }
    try {
      const res = await fetch(
        `http://localhost:3004/api/employees/${employeeId}/change-password`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ oldPassword: oldPass, newPassword: newPass }),
        }
      );
      if (!res.ok) throw new Error("Password change failed");
      alert("Password changed successfully!");
      setOldPass("");
      setNewPass("");
    } catch (err) {
      alert(err.message);
    }
  };

  if (!employee) return <p className="text-center mt-5">Loading...</p>;

  return (
    <div className="container mt-5">
      <div className="profile-header">Employee Profile</div>

      <div className="profile-card">
        <div className="row">
          <div className="col-md-4 text-center">
            <div className="profile-icon">
              <FaUserCircle size={120} color="#C7D9DD" />
            </div>
            <div className="mt-2">
              <label className="form-label">Update Image URL</label>
              <input
                type="text"
                className="form-control"
                value={editImage}
                onChange={(e) => setEditImage(e.target.value)}
              />
            </div>
          </div>

          <div className="col-md-8">
            <table className="table table-borderless">
              <tbody>
                <tr>
                  <th>Name:</th>
                  <td>{employee.name}</td>
                </tr>
                <tr>
                  <th>Email:</th>
                  <td>{employee.email}</td>
                </tr>
                <tr>
                  <th>Contact:</th>
                  <td>
                    <input
                      type="text"
                      className="form-control"
                      value={editContact}
                      onChange={(e) => setEditContact(e.target.value)}
                    />
                  </td>
                </tr>
                <tr>
                  <th>Designation:</th>
                  <td>{employee.designation}</td>
                </tr>
                <tr>
                  <th>Department:</th>
                  <td>{employee.department}</td>
                </tr>
                <tr>
                  <th>Joining Date:</th>
                  <td>{new Date(employee.joiningDate).toLocaleDateString()}</td>
                </tr>
              </tbody>
            </table>
            <button className="btn-glow mt-3" disabled onClick={handleProfileUpdate}>
              Update Profile
            </button>
          </div>
        </div>
      </div>

      <div className="profile-card mt-4">
        <h5 className="text-purple">Change Password</h5>
        <form onSubmit={handleChangePassword}>
          <div className="mb-3">
            <label className="form-label">Old Password</label>
            <input
              type="password"
              className="form-control"
              value={oldPass}
              onChange={(e) => setOldPass(e.target.value)}
            />
          </div>
          <div className="mb-3">
            <label className="form-label">New Password</label>
            <input
              type="password"
              className="form-control"
              value={newPass}
              onChange={(e) => setNewPass(e.target.value)}
            />
          </div>
          <button type="submit" className="btn-glow" disabled>
            Change Password
          </button>
        </form>
      </div>
    </div>
  );
}
