import React, { useState, useEffect } from "react";
import 'bootstrap/dist/css/bootstrap.min.css';
import axios from "../Https/Axios";
import { jwtDecode } from "jwt-decode";
import { FaSignInAlt, FaSignOutAlt, FaClock, FaBriefcase } from "react-icons/fa";

export default function Attendance() {
  const [checkedIn, setCheckedIn] = useState(false);
  const [checkedOut, setCheckedOut] = useState(false);
  const [checkInTime, setCheckInTime] = useState(null);
  const [checkOutTime, setCheckOutTime] = useState(null);
  const [breaks, setBreaks] = useState([]);
  const [onBreak, setOnBreak] = useState(false);
  const [currentBreakStart, setCurrentBreakStart] = useState(null);
  const [timer, setTimer] = useState("00:00:00");
  const [report, setReport] = useState(null);

  const token = localStorage.getItem("emsemployeelogintoken");
  const decoded = token ? jwtDecode(token) : {};
  const employeeId = decoded.id;

  useEffect(() => {
    fetchReport();
  }, []);



  useEffect(() => {
    let interval = null;

    if (report && report.netWorkedMs != null && checkedIn && !checkedOut && !onBreak) {
      let ms = report.netWorkedMs;

      interval = setInterval(() => {
        ms += 1000;
        const h = Math.floor(ms / 3600000).toString().padStart(2, "0");
        const m = Math.floor((ms % 3600000) / 60000).toString().padStart(2, "0");
        const s = Math.floor((ms % 60000) / 1000).toString().padStart(2, "0");
        setTimer(`${h}:${m}:${s}`);
      }, 1000);
    } else {
      setTimer("00:00:00");
    }

    return () => clearInterval(interval);
  }, [report, checkedIn, checkedOut, onBreak]);

  const handleCheckIn = async () => {
    if (!checkedIn && employeeId) {
      const now = new Date();
      try {
        await axios.post("/api/attendances/checkin", { employeeId });
        setCheckedIn(true);
        setCheckInTime(now);
        setCheckedOut(false);
        setBreaks([]);
        setOnBreak(false);
        setCurrentBreakStart(null);
        fetchReport();
      } catch (error) {
        console.error("Check-in failed", error);
      }
    }
  };

  const handleCheckOut = async () => {
    if (checkedIn && !checkedOut && employeeId) {
      if (onBreak) {
        await handleBreakToggle(); // ensure break ends
      }
      const now = new Date();
      try {
        await axios.post("/api/attendances/checkout", { employeeId });
        setCheckedOut(true);
        setCheckOutTime(now);
        fetchReport();
      } catch (error) {
        console.error("Check-out failed", error);
      }
    }
  };

  const handleBreakToggle = async () => {
    if (!employeeId) return;

    if (onBreak) {
      const now = new Date();
      try {
        await axios.post("/api/attendances/break/end", { employeeId });
        setBreaks(prev => [...prev, { start: currentBreakStart, end: now }]);
        setOnBreak(false);
        setCurrentBreakStart(null);
        fetchReport();
      } catch (error) {
        console.error("Ending break failed", error);

      }
    } else {
      try {
        await axios.post("/api/attendances/break/start", { employeeId });
        setOnBreak(true);
        setCurrentBreakStart(new Date());
        fetchReport();
      } catch (error) {
        console.error("Starting break failed", error);
      }
    }
  };

  const getTotalBreakMinutes = () => {
    let total = breaks.reduce((sum, b) => sum + (b.end - b.start), 0);
    if (onBreak && currentBreakStart) {
      total += (new Date() - currentBreakStart);
    }
    return Math.floor(total / 60000);
  };

  const getWorkingMinutes = () => {
    if (!checkInTime || !checkOutTime) return 0;
    const total = (checkOutTime - checkInTime) / 60000;
    const breaksMins = getTotalBreakMinutes();
    return Math.max(0, Math.floor(total - breaksMins));
  };



  const fetchReport = async () => {
    if (!employeeId) return;

    const today = new Date().toISOString().split("T")[0];
    try {
      const response = await axios.get(`/api/attendances/report/${employeeId}/${today}`);
      const data = response.data;

      setReport(data);

      // Hydrate states
      if (data.checkIn) {
        setCheckedIn(true);
        setCheckInTime(new Date(data.checkIn));
      }
      if (data.checkOut) {
        setCheckedOut(true);
        setCheckOutTime(new Date(data.checkOut));
      }

      const backendBreaks = data.breaks || [];
      setBreaks(backendBreaks.map(b => ({
        start: new Date(b.breakStart),
        end: b.breakEnd ? new Date(b.breakEnd) : null,
      })));

      const ongoing = backendBreaks.find(b => b.breakStart && !b.breakEnd);
      setOnBreak(!!ongoing);
      setCurrentBreakStart(ongoing ? new Date(ongoing.breakStart) : null);

    } catch (error) {
      console.error("Fetching report failed", error);
    }
  };



  return (
<div className="container py-4">
  {/* Row 1: Heading */}
  <div className="row mb-4">
    <div className="col text-center">
      <h2 className="fw-bold text-dark" style={{ letterSpacing: "1.5px" }}>
         Attendance Tracker
      </h2>
    </div>
  </div>

  {/* Row 2: Timer */}
  <div className="row mb-4 justify-content-center">
    <div className="col-auto">
      <div
        className="text-dark px-4 py-2 rounded-3 shadow-sm text-center"
        style={{
          fontSize: "3rem",
          fontWeight: "900",
          color: onBreak ? "#FF4081" : "#000",
          background: onBreak ? "#ffe6ef" : "#f0f0f0",
          minWidth: "180px"
        }}
      >
        {onBreak ? "BREAK" : timer}
      </div>
    </div>
  </div>

  {/* Row 3: Action Icons */}
  <div className="row mb-4 text-center g-4 justify-content-center">
    {/* Check In */}
    <div className="col-md-3">
      <div className="shadow bg-white rounded p-4">
        <i className="fas fa-sign-in-alt"
          onClick={handleCheckIn}
          style={{
            fontSize: "5rem",
            color: checkedIn ? "#888" : "#E100FF",
            cursor: checkedIn ? "not-allowed" : "pointer",
            transition: "transform 0.3s"
          }}
          onMouseEnter={e => !checkedIn && (e.currentTarget.style.transform = "scale(1.2)")}
          onMouseLeave={e => (e.currentTarget.style.transform = "scale(1)")}
        ></i>
        <div className="fw-bold mt-2" style={{ opacity: checkedIn ? 0.6 : 1 }}>Check In</div>
      </div>
    </div>

    {/* Break */}
    <div className="col-md-3">
      <div className="shadow bg-white rounded p-4">
        <i className="fas fa-coffee"
          onClick={handleBreakToggle}
          style={{
            fontSize: "5rem",
            color: onBreak ? "#FF4081" : "#aaa",
            cursor: (!checkedIn || checkedOut) ? "not-allowed" : "pointer",
            transition: "transform 0.3s",
            opacity: (!checkedIn || checkedOut) ? 0.5 : 1
          }}
          onMouseEnter={e => (!checkedOut && checkedIn) && (e.currentTarget.style.transform = "scale(1.2)")}
          onMouseLeave={e => (e.currentTarget.style.transform = "scale(1)")}
        ></i>
        <div className="fw-bold mt-2">{onBreak ? "End Break" : "Start Break"}</div>
      </div>
    </div>

    {/* Check Out */}
    <div className="col-md-3">
      <div className="shadow bg-white rounded p-4">
        <i className="fas fa-sign-out-alt"
          onClick={handleCheckOut}
          style={{
            fontSize: "5rem",
            color: (!checkedIn || checkedOut) ? "#888" : "#E100FF",
            cursor: (!checkedIn || checkedOut) ? "not-allowed" : "pointer",
            transition: "transform 0.3s",
            opacity: (!checkedIn || checkedOut) ? 0.6 : 1
          }}
          onMouseEnter={e => (!checkedOut && checkedIn) && (e.currentTarget.style.transform = "scale(1.2)")}
          onMouseLeave={e => (e.currentTarget.style.transform = "scale(1)")}
        ></i>
        <div className="fw-bold mt-2" style={{ opacity: (!checkedIn || checkedOut) ? 0.6 : 1 }}>Check Out</div>
      </div>
    </div>
  </div>

  {/* Row 4: Summary Cards */}
  {report && (
    <div className="row g-4">
      {/* Check-In Card */}
      <div className="col-md-3">
        <div className="card shadow rounded-4 border-0 bg-light text-center">
          <div className="card-body">
            <div className="mb-2 text-success fs-3"><FaSignInAlt /></div>
            <h6 className="card-title fw-bold">Check-In</h6>
            <p className="text-muted">{report.checkIn ? new Date(report.checkIn).toLocaleTimeString() : "N/A"}</p>
          </div>
        </div>
      </div>

      {/* Check-Out Card */}
      <div className="col-md-3">
        <div className="card shadow rounded-4 border-0 bg-light text-center">
          <div className="card-body">
            <div className="mb-2 text-danger fs-3"><FaSignOutAlt /></div>
            <h6 className="card-title fw-bold">Check-Out</h6>
            <p className="text-muted">{report.checkOut ? new Date(report.checkOut).toLocaleTimeString() : "N/A"}</p>
          </div>
        </div>
      </div>

      {/* Break Time */}
      <div className="col-md-3">
        <div className="card shadow rounded-4 border-0 bg-light text-center">
          <div className="card-body">
            <div className="mb-2 text-warning fs-3"><FaClock /></div>
            <h6 className="card-title fw-bold">Total Break (min)</h6>
            <p className="text-muted">{getTotalBreakMinutes()} min</p>
          </div>
        </div>
      </div>

      {/* Net Work Time */}
      <div className="col-md-3">
        <div className="card shadow rounded-4 border-0 bg-light text-center">
          <div className="card-body">
            <div className="mb-2 text-primary fs-3"><FaBriefcase /></div>
            <h6 className="card-title fw-bold">Net Worked (min)</h6>
            <p className="text-muted">{getWorkingMinutes()} min</p>
          </div>
        </div>
      </div>
    </div>
  )}
</div>




  );
}