import React, { useEffect, useState } from "react";
import { useNavigate, NavLink } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import {
  FaHome, FaCalendarCheck, FaListAlt, FaProjectDiagram,
  FaUserCircle, FaBell, FaBug, FaRegCalendarMinus
} from "react-icons/fa";
import axios from "../Https/Axios";
import { jwtDecode } from "jwt-decode";
import Cookies from "js-cookie";



export default function DashBoardNavbar({ onItemClick }) {
  const [isOpen, setIsOpen] = useState(false);
  const [employeeName, setEmployeeName] = useState("");
  const navigate = useNavigate();

  // Fetch employee name using token => decode id => fetch with /employee/:id
  useEffect(() => {
    const fetchEmployee = async () => {
      const token = localStorage.getItem("emsemployeelogintoken");
      if (!token) return;

      try {
        const decoded = jwtDecode(token);
        const employeeId = decoded.id || decoded._id; // depends on token structure
        console.log (employeeId)
        const res = await axios.get(`/api/employees/${employeeId}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        setEmployeeName(res.data.name);
      } catch (err) {
        console.error("Failed to fetch employee:", err);
      }
    };

    fetchEmployee();
  }, []);

  const handleToggle = () => setIsOpen(!isOpen);
const handleLogout = () => {
  Cookies.remove("emsemployeelogintoken", { path: "/" });
  navigate("/");
};

  const navItems = [
    { path: "/home", icon: <FaHome className="me-2" />, label: "Home" },
    { path: "/attendance", icon: <FaCalendarCheck className="me-2" />, label: "Attendance" },
    { path: "/attendancedetail", icon: <FaListAlt className="me-2" />, label: "AttendanceLog" },
    { path: "/project", icon: <FaProjectDiagram className="me-2" />, label: "Project" },
    { path: "/profile", icon: <FaUserCircle className="me-2" />, label: "Profile" },
    { path: "/notification", icon: <FaBell className="me-2" />, label: "Notification" },
    { path: "/reportproblem", icon: <FaBug className="me-2" />, label: "Problems" },
    { path: "/leaveapplication", icon: <FaRegCalendarMinus className="me-2" />, label: "Leaves" },
  ];

  return (
    <>
    {/* Top Fixed Navbar (with logo + toggle) */}
<div
  className="d-flex align-items-center justify-content-between px-3 py-2 bg-green-500 text-white position-fixed w-100 d-lg-none d-md-none"
  style={{ top: 0, left: 0, zIndex: 1100, height: "60px" }}
>
  {/* Logo or Title */}
  <div className="fw-bold fs-5">
    <i className="fas fa-leaf me-2"></i> EMS Dashboard
  </div>

  {/* Mobile Toggle Button */}
  <button
    className="d-md-none btn btn-sm text-white"
    onClick={handleToggle}
    style={{ fontSize: "20px" }}
  >
    <i className="fas fa-bars"></i>
  </button>
</div>


      {/* Mobile Sidebar */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ x: "-100%" }}
            animate={{ x: 0 }}
            exit={{ x: "-100%" }}
            transition={{ type: "spring", stiffness: 300, damping: 30 }}
            className="position-fixed bg-white border-end shadow d-flex flex-column justify-content-between"
            style={{
              top: 0, left: 0, height: "100vh", width: "250px", zIndex: 1040,
              borderTopRightRadius: "1.5rem", borderBottomRightRadius: "1.5rem", overflowY: "auto"
            }}
          >
            <div>
              <div className="d-flex justify-content-between align-items-center bg-green-500 text-white p-3">
                <h5 className="w-100 text-center m-0 fw-bold">Welcome {employeeName || "..."}</h5>
                <button className="btn btn-sm text-white d-md-none" onClick={handleToggle}>
                  <i className="fas fa-times"></i>
                </button>
              </div>
              <ul className="list-unstyled mt-5 d-flex flex-column align-items-center p-3" style={{ fontSize: "15px" }}>
                {navItems.map((item, index) => (
                  <li key={index} style={{ width: "100%" }}>
                    <NavLink
                      to={item.path}
                      className={({ isActive }) =>
                        `nav-link custom-link d-flex align-items-center gap-2 px-4 py-2 ${isActive ? "text-green-500" : ""}`
                      }
                      onClick={() => setIsOpen(false)}
                    >
                      {item.icon}
                      {item.label}
                    </NavLink>
                  </li>
                ))}
              </ul>
            </div>
            <div className="p-3">
              <div
                className="d-flex align-items-center gap-2 p-3 bg-green-500 rounded"
                style={{ cursor: "pointer" }}
                onClick={handleLogout}
              >
                <i className="fas fa-sign-out-alt"></i>
                <span className="fw-bold text-light">Logout</span>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Desktop Sidebar */}
      <div
        className="d-none d-md-flex flex-column justify-content-between position-fixed bg-white shadow"
        style={{
          top: 0, left: 0, height: "100vh", width: "250px",
          borderTopRightRadius: "1.5rem", borderBottomRightRadius: "1.5rem", zIndex: 1030,
        }}
      >
        <div>
          <div className="bg-green-500 text-white text-center fs-5 fw-bold py-3"
            style={{ borderBottomLeftRadius: "1.5rem", borderTopRightRadius: "1.5rem" }}>
            Welcome {employeeName || "..."}
          </div>
          <ul className="list-unstyled mt-5 d-flex flex-column align-items-center p-3" style={{ fontSize: "15px" }}>
            {navItems.map((item, index) => (
              <li key={index} style={{ width: "100%" }}>
                <NavLink
                  to={item.path}
                  className={({ isActive }) =>
                    `nav-link custom-link d-flex align-items-center gap-2 px-4 py-2 ${isActive ? "text-green-500" : ""}`
                  }
                >
                  {item.icon}
                  {item.label}
                </NavLink>
              </li>
            ))}
          </ul>
        </div>
        <div className="pb-5 ps-3">
          <div
            className="d-flex align-items-center gap-2 p-3 text-dark bg-green-500"
            style={{ cursor: "pointer", borderTopLeftRadius: "20px", borderBottomLeftRadius: "20px" }}
            onClick={handleLogout}
          >
            <i className="fas fa-sign-out-alt"></i>
            <span className="fw-bold">Logout</span>
          </div>
        </div>
      </div>

      {/* Overlay */}
      {isOpen && (
        <div
          className="position-fixed top-0 start-0 w-100 h-100 d-md-none"
          style={{ backgroundColor: "rgba(0,0,0,0.4)", zIndex: 1020 }}
          onClick={handleToggle}
        />
      )}
    </>
  );
}
