import React, { useState, useEffect } from "react";
import Axios from "../Https/Axios";
import { Leaves } from "../Https/AdminSideAxiosUrls";
import { jwtDecode } from "jwt-decode";

export default function LeaveApplication() {
  const [leaveData, setLeaveData] = useState({
    leaveType: "Sick",
    fromDate: "",
    toDate: "",
    reason: ""
  });

  const [history, setHistory] = useState([]);
  const [showForm, setShowForm] = useState(false);

  const token = localStorage.getItem("emsemployeelogintoken");
  let employeeId = null;

  try {
    const decoded = token ? jwtDecode(token) : {};
    employeeId = decoded.id;
  } catch (err) {
    console.error("Invalid token:", err);
  }

  useEffect(() => {
    fetchLeaveHistory();
  }, []);

  const fetchLeaveHistory = async () => {
    try {
      const response = await Axios.get(`${Leaves}/employee/${employeeId}`);
      setHistory(response.data);
    } catch (error) {
      console.error("Error fetching leave history:", error);
    }
  };

  const handleChange = (e) => {
    setLeaveData({ ...leaveData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newApplication = {
      employeeId,
      leaveType: leaveData.leaveType,
      fromDate: leaveData.fromDate,
      toDate: leaveData.toDate,
      reason: leaveData.reason,
      status: "Pending",
      adminRemarks: ""
    };

    try {
      await Axios.post(Leaves, newApplication);
      fetchLeaveHistory();
      setLeaveData({ leaveType: "Sick", fromDate: "", toDate: "", reason: "" });
      setShowForm(false);
    } catch (error) {
      console.error("Error submitting leave application:", error);
    }
  };

  return (
    <div className="container py-4">
      {/* Header Section */}
      <div className="d-flex justify-content-between align-items-center mb-4">
         <h3 className="fw-bold" >
          Leaves History
        </h3>
        <button
          className="btn text-white fw-bold bg-green-500"
          style={{ padding: "10px 20px" }}
          onClick={() => setShowForm(true)}
        >
          Apply for Leave
        </button>
       
      </div>

      {/* Leave Form */}
      {showForm && (
        <div
          className="position-fixed top-0 start-0 w-100 h-100 d-flex justify-content-center align-items-center"
          style={{ backgroundColor: "rgba(0,0,0,0.6)", zIndex: 1050 }}
        >
          <div className="bg-white p-4 rounded shadow" style={{ maxWidth: "500px", width: "100%" }}>
            <h4
              className="text-center fw-bold mb-4"
              style={{
                background: "linear-gradient(to right, #ff0055, #E100FF)",
                WebkitBackgroundClip: "text",
                WebkitTextFillColor: "transparent"
              }}
            >
              Leave Application
            </h4>
            <form onSubmit={handleSubmit}>
              <div className="mb-3">
                <label className="form-label">Leave Type</label>
                <select className="form-select" name="leaveType" value={leaveData.leaveType} onChange={handleChange}>
                  <option value="Sick">Sick</option>
                  <option value="Casual">Casual</option>
                  <option value="Paid">Paid</option>
                </select>
              </div>
              <div className="mb-3">
                <label className="form-label">From Date</label>
                <input type="date" className="form-control" name="fromDate" value={leaveData.fromDate} onChange={handleChange} required />
              </div>
              <div className="mb-3">
                <label className="form-label">To Date</label>
                <input type="date" className="form-control" name="toDate" value={leaveData.toDate} onChange={handleChange} required />
              </div>
              <div className="mb-3">
                <label className="form-label">Reason</label>
                <textarea className="form-control" name="reason" value={leaveData.reason} onChange={handleChange} required />
              </div>
              <div className="d-flex justify-content-between">
                <button type="submit" className="btn text-white fw-bold" style={{ backgroundColor: "#ff0055" }}>
                  Submit
                </button>
                <button type="button" className="btn btn-secondary" onClick={() => setShowForm(false)}>
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Leave History Cards */}
      <div className="mt-4">
        {history.length === 0 ? (
          <p className="text-muted fst-italic">No leave applications yet.</p>
        ) : (
          history.map((item, index) => (
            <div key={item._id} className="mb-4">
              <div
                className=" text-white shadow w-100 p-3"
                style={{
                  backgroundColor: index % 2 === 0 ? "#ff0055" : "#E100FF",
                  borderRadius: "12px"
                }}
              >
                {/* Header Row */}
                <div className="row align-items-center mb-2">
                  <div className="col-md-6">
                    <h5 className="mb-2">
                      <i className="fas fa-plane-departure me-2"></i>
                      {item.leaveType} Leave
                    </h5>
                  </div>
                  <div className="col-md-6 text-md-end">
                    <span className="me-3">
                      <strong>From:</strong> {new Date(item.fromDate).toLocaleDateString()}
                    </span>
                    <span className="me-3">
                      <strong>To:</strong> {new Date(item.toDate).toLocaleDateString()}
                    </span>
                    <span className="badge bg-light text-dark">{item.status}</span>
                  </div>
                </div>

                {/* Reason */}
                <div className="mb-2">
                  <strong>Reason:</strong> {item.reason}
                </div>

                {/* Admin Remarks */}
                <div>
                  <strong>Admin Remarks:</strong>{" "}
                  <span className="fst-italic">
                    {item.adminRemarks ? item.adminRemarks : "N/A"}
                  </span>
                </div>
              </div>
            </div>

          ))
        )}
      </div>
    </div>
  );
}
