import React, { useEffect, useState } from 'react';
import './App.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Routes, Route, Navigate } from 'react-router-dom';
import Cookies from 'js-cookie';

import Login from './components/Login';
import Dashboard from './components/Dashboard';
import DashboardHome from './components/DashboardHome';
import Attendance from './components/Attendance';
import AttendanceDetail from './components/AttendanceDetail';
import Project from './components/Project';
import Profile from './components/Profile';
import Notification from './components/Notification';
import ReportProblem from './components/ReportProblem';
import LeaveApplication from './components/LeaveApplication';

function App() {
  const [loading, setLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
console.log(isAuthenticated)
  useEffect(() => {
    const timer = setTimeout(() => setLoading(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    const token = Cookies.get('emsemployeelogintoken');
    setIsAuthenticated(!!token);
  }, []);

  if (loading) {
    return (
      <div className="loader-wrapper">
        <div className="neon-loader"><span></span><span></span><span></span><span></span></div>
        <h2 className="loader-text">Loading, please wait...</h2>
      </div>
    );
  }

  return (
    <Routes>
      <Route 
        path="/" 
        element={<Login setIsAuthenticated={setIsAuthenticated} />} 
      />
      {isAuthenticated ? (
        <>
          <Route path="/dashboardhome" element={<Dashboard><DashboardHome /></Dashboard>} />
          <Route path="/attendance" element={<Dashboard><Attendance /></Dashboard>} />
          <Route path="/attendancedetail" element={<Dashboard><AttendanceDetail /></Dashboard>} />
          <Route path="/project" element={<Dashboard><Project /></Dashboard>} />
          <Route path="/profile" element={<Dashboard><Profile /></Dashboard>} />
          <Route path="/notification" element={<Dashboard><Notification /></Dashboard>} />
          <Route path="/reportproblem" element={<Dashboard><ReportProblem /></Dashboard>} />
          <Route path="/leaveapplication" element={<Dashboard><LeaveApplication /></Dashboard>} />
        </>
      ) : (
        <Route path="*" element={<Navigate to="/" />} />
      )}
    </Routes>
  );
}

export default App;
