import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { FaSignInAlt, FaEye, FaEyeSlash } from "react-icons/fa";
import Axios from "../Https/Axios"; 
import { login } from "../Https/AdminSideAxiosUrls"; 
import Cookies from "js-cookie";

export default function Login({ setIsAuthenticated }) {  // receive setIsAuthenticated as prop
  const [showPassword, setShowPassword] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [isLoggingIn, setIsLoggingIn] = useState(false); 
  const navigate = useNavigate();

  const togglePassword = () => setShowPassword(prev => !prev);

  const handleLoginClick = async () => {
    if (!email || !password) {
      alert("Please enter email and password");
      return;
    }
    setIsLoggingIn(true);

    try {
      const response = await Axios.post(login, { email, password });
      Cookies.set("emsemployeelogintoken", response.data.token, { expires: 1 });

      // Update authentication state here
      setIsAuthenticated(true);

      navigate("/dashboardhome");
    } catch (error) {
      console.error("Login error:", error);
      alert("Login failed. Please try again.");
    } finally {
      setIsLoggingIn(false);
    }
  };
  
  return (
    <div className="d-flex justify-content-center align-items-center vh-100 login-container">
      <div className="p-5 shadow-lg login-card" style={{ minWidth: "320px" }}>
        <div className="text-center mb-4">
          <FaSignInAlt size={40} className="login-icon" />
          <h3 className="mt-2">Welcome Back!</h3>
          <p className="text-muted login-subtitle">Please login to your account</p>
        </div>

        <div className="mb-3">
          <label className="form-label fw-semibold">Email address</label>
          <input
            type="email"
            className="form-control input-rounded"
            placeholder="Enter your email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
        </div>

        <div className="mb-4 position-relative">
          <label className="form-label fw-semibold">Password</label>
          <input
            type={showPassword ? "text" : "password"}
            className="form-control input-rounded"
            placeholder="Enter password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{ paddingRight: "40px" }}
            required
          />
          <span
            onClick={togglePassword}
            className="password-toggle mt-2"
            style={{ cursor: "pointer", position: "absolute", right: "10px", top: "38px" }}
          >
            {showPassword ? <FaEyeSlash /> : <FaEye />}
          </span>
        </div>

        <button
          onClick={handleLoginClick}
          className="btn w-100 text-white fw-bold login-button"
          disabled={isLoggingIn}
        >
          {isLoggingIn ? "Please wait..." : "Login"}
        </button>
      </div>
    </div>
  );
}