import React, { useEffect, useState } from "react";
import { FaCheckCircle, FaHourglass } from "react-icons/fa";
import Axios from "../Https/Axios";
import { Reports } from "../Https/AdminSideAxiosUrls";
import { jwtDecode } from "jwt-decode";
import { color } from "framer-motion";

export default function ReportProblem() {
  const [problems, setProblems] = useState([]);
  const [category, setCategory] = useState("Technical");
  const [subject, setSubject] = useState("");
  const [description, setDescription] = useState("");
  const [showModal, setShowModal] = useState(false);

  const gradientBtn = "linear-gradient(135deg, #ff0099, #b800ff)";
  const cardGradient = "linear-gradient(135deg, #b800ff, #ff0099)";

  // Decode token to get employeeId
  const token = localStorage.getItem("emsemployeelogintoken");
  let employeeId = null;

  try {
    const decoded = token ? jwtDecode(token) : {};
    employeeId = decoded.id;
  } catch (err) {
    console.error("Invalid token:", err);
  }

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const response = await Axios.get(`${Reports}/employee/${employeeId}`);
      setProblems(response.data);
    } catch (error) {
      console.error("Failed to fetch problems:", error);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!subject.trim() || !description.trim()) {
      alert("Please enter both subject and description.");
      return;
    }

    if (!employeeId) {
      alert("Invalid or missing employee ID. Please log in again.");
      return;
    }

    const payload = {
      employeeId,
      reportType: "problem",
      title: subject,
      description,
      category,
      status: "Open",
    };

    try {
      const response = await Axios.post(Reports, payload, {
        headers: {
          "Content-Type": "application/json",
        },
      });

      setProblems([response.data, ...problems]);
      setSubject("");
      setDescription("");
      setCategory("Technical");
      setShowModal(false);
    } catch (error) {
      console.error("Failed to submit problem:", error);
      alert("Failed to submit problem.");
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this problem?")) return;

    try {
      await Axios.delete(`${Reports}/${id}`);
      setProblems(problems.filter((problem) => problem._id !== id));
    } catch (error) {
      console.error("Failed to delete problem:", error);
      alert("Failed to delete problem.");
    }
  };

  return (
    <div className="container py-4">
     <div className="d-flex justify-content-between align-items-center mb-4">
  <h1 className="fs-2 m-0">Problems</h1>

  <div>
    <button
      className="btn text-white fw-bold"
      style={{
        background: gradientBtn,
        border: "none",
        padding: "12px 24px",
        borderRadius: "8px",
      }}
      onClick={() => setShowModal(true)}
    >
      Report a Problem
    </button>
  </div>
</div>


      {/* Modal */}
      {showModal && (
        <div
          className="modal fade show d-block"
          tabIndex="-1"
          style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
        >
          <div className="modal-dialog modal-lg modal-dialog-centered">
            <div className="modal-content rounded-4">
              <div className="modal-header">
                <h5 className="modal-title">Report a Problem</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowModal(false)}
                ></button>
              </div>
              <div className="modal-body">
                <form onSubmit={handleSubmit}>
                  <div className="mb-3">
                    <label className="form-label fw-semibold">Category</label>
                    <select
                      className="form-select"
                      value={category}
                      onChange={(e) => setCategory(e.target.value)}
                      required
                    >
                      <option value="Technical">Technical</option>
                      <option value="Other">Other</option>
                    </select>
                  </div>

                  <div className="mb-3">
                    <label className="form-label fw-semibold">Subject</label>
                    <input
                      type="text"
                      className="form-control"
                      placeholder="Enter subject"
                      value={subject}
                      onChange={(e) => setSubject(e.target.value)}
                      required
                    />
                  </div>

                  <div className="mb-3">
                    <label className="form-label fw-semibold">Description</label>
                    <textarea
                      className="form-control"
                      placeholder="Describe the issue"
                      rows="4"
                      value={description}
                      onChange={(e) => setDescription(e.target.value)}
                      required
                    ></textarea>
                  </div>

                  <button
                    type="submit"
                    className="btn text-white w-100 fw-semibold"
                    style={{
                      background: gradientBtn,
                      border: "none",
                      borderRadius: "8px",
                      padding: "12px",
                      fontSize: "16px",
                    }}
                  >
                    Submit
                  </button>
                </form>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Submitted Problems */}
     {/* Submitted Problems */}
{problems.length > 0 ? (
  <div className="row mt-5">
    {problems.map((problem) => (
      <div className="col-lg-12 col-md-12 mx-auto mb-4" key={problem._id}>
        <div
          className="card shadow-sm border-0 rounded-4 h-100"
          style={{
            background: "#b800ff",
            color: "#333",
            borderLeft: "5px solid #b800ff",
          }}
        >
          <div className="card-body">
            <div className="d-flex justify-content-between align-items-start mb-2">
              <h5 className="card-title text-light">{problem.title}</h5>
              <div>
                <span
                  className="badge px-3 py-2 bg-light rounded-pill text-white"
                  style={{
                    background:
                      problem.status === "Open" ? gradientBtn : "white",
                  }}
                >
                  {problem.status === "Open" ? (
                    <>
                      <FaHourglass className="me-1" />
                      Pending
                    </>
                  ) : (
                    <>
                      <FaCheckCircle className="me-1 text-dark" />
                  <span className="text-dark">    Resolved  </span>
                    </>
                  )}
                </span>
                <button
                  className="btn rounded-pill text-white btn-sm px-4 ms-md-2"
                  onClick={() => handleDelete(problem._id)}
                  style={{ background: gradientBtn }}
                >
                  Delete
                </button>
              </div>
            </div>
            <h6 className="fst-italic mb-2 text-light">
              Category: {problem.category || "Other"}
            </h6>
            <p className="card-text text-light">{problem.description}</p>
          </div>
        </div>
      </div>
    ))}
  </div>
) : (
  <div className="text-center text-muted mt-5 fs-5">
    You have not reported any problem yet.
  </div>
)}

    </div>
  );
}